package com.amdocs.telecom.validation; import java.util.*; public final class Validators{private Validators(){}public static String required(Map<String,Object> m,String k){Object v=m.get(k);if(v==null||String.valueOf(v).trim().isEmpty())throw new IllegalArgumentException(k+" is required");return String.valueOf(v).trim();}public static int integer(Map<String,Object>m,String k,int min,int max){int v=Integer.parseInt(required(m,k));if(v<min||v>max)throw new IllegalArgumentException(k+" out of range");return v;}}
